// Client mapping lookup
const clientMapping = [
  { id: '1', name: 'Joseph Bui', brand: 'Open House Finance', adAccountId: 'act_PLACEHOLDER_1', bmType: 'own', currency: 'USD' },
  { id: '2', name: 'Matt Tixier', brand: 'True Mortgage', adAccountId: 'act_PLACEHOLDER_2', bmType: 'agency', currency: 'USD' },
  { id: '3', name: 'Richard Weinberg', brand: 'Rich Capital', adAccountId: 'act_PLACEHOLDER_3', bmType: 'own', currency: 'USD' },
  { id: '4', name: 'John Flanders', brand: 'Karpata Finance', adAccountId: 'act_PLACEHOLDER_4', bmType: 'agency', currency: 'USD' },
  { id: '5', name: 'Matthew Silva', brand: 'Woodlands', adAccountId: 'act_PLACEHOLDER_5', bmType: 'agency', currency: 'USD' },
  { id: '6', name: 'Derek Schaffer', brand: 'Investor Capital Loans NJ', adAccountId: 'act_1501251134615354', bmType: 'own', currency: 'USD' },
  { id: '7', name: 'Paul Healey', brand: 'Spectrum One Mortgage', adAccountId: 'act_PLACEHOLDER_7', bmType: 'agency', currency: 'USD' },
  { id: '8', name: 'Jason Gilmore', brand: 'James Paxton Mortgages', adAccountId: 'act_PLACEHOLDER_8', bmType: 'agency', currency: 'USD' },
  { id: '9', name: 'Dan Nguyen', brand: 'Win Capital LLC', adAccountId: 'act_PLACEHOLDER_9', bmType: 'own', currency: 'USD' },
  { id: '10', name: 'Chad', brand: 'Canada Mortgage Direct', adAccountId: 'act_PLACEHOLDER_10', bmType: 'own', currency: 'CAD' },
  { id: '11', name: 'Kelto', brand: 'Quebec Refinance', adAccountId: 'act_PLACEHOLDER_11', bmType: 'own', currency: 'CAD' },
  { id: '12', name: 'Shaun Woods', brand: 'Opus Grenero', adAccountId: 'act_PLACEHOLDER_12', bmType: 'agency', currency: 'USD' },
  { id: '13', name: 'Dean Onwumere', brand: 'Part 2 Lending', adAccountId: 'act_PLACEHOLDER_13', bmType: 'agency', currency: 'USD' },
  { id: '14', name: 'Benjamin Gerritsen', brand: 'Mortgage Miracles', adAccountId: 'act_PLACEHOLDER_14', bmType: 'agency', currency: 'USD' },
  { id: '15', name: 'Natalie x Brian', brand: 'NB Capital', adAccountId: 'act_PLACEHOLDER_15', bmType: 'own', currency: 'USD' }
];

const body = $input.first().json.body || {};
const clientId = body.clientId;

if (!clientId) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'clientId is required' } }];
}

const client = clientMapping.find(c => c.id === clientId);
if (!client) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'Client ID not found in mapping' } }];
}

return [{ json: { ...client, clientId } }];

const client = $('Resolve Client').first().json;
const campaignsResponse = $('Get Campaigns').first().json;
const insightsResponse = $('Get Account Insights').first().json;

const campaigns = campaignsResponse.body?.data || campaignsResponse.data || [];
const insights = insightsResponse.body?.data?.[0] || insightsResponse.data?.[0] || {};

const spend = parseFloat(insights.spend || 0);
const impressions = parseInt(insights.impressions || 0);
const cpm = parseFloat(insights.cpm || 0);
const ctr = parseFloat(insights.ctr || 0);
const frequency = parseFloat(insights.frequency || 0);

// Calculate double-counting
const actions = insights.actions || [];
const reportedLeads = parseInt(actions.find(a => a.action_type === 'lead')?.value || 0);
const trueLeads = parseInt(actions.find(a => a.action_type === 'onsite_conversion.lead_grouped')?.value || reportedLeads);
const doubleCount = reportedLeads > 0 && trueLeads > 0 && (reportedLeads / trueLeads) > 1.1;
const inflation = reportedLeads > 0 && trueLeads > 0 ? ((reportedLeads - trueLeads) / trueLeads * 100).toFixed(0) : '0';
const blendedCpl = reportedLeads > 0 ? (spend / reportedLeads) : null;
const trueCpl = trueLeads > 0 ? (spend / trueLeads) : null;

// Check alert thresholds
const alerts = [];
if (cpm > 150) alerts.push({ type: 'high_cpm', client: client.clientId, value: cpm });
if (frequency > 3.5) alerts.push({ type: 'high_frequency', client: client.clientId, value: frequency });
if (doubleCount) alerts.push({ type: 'double_count', client: client.clientId, inflation: inflation + '%' });
if (trueCpl > 80) alerts.push({ type: 'high_cpl', client: client.clientId, value: trueCpl });

return [{
  json: {
    success: true,
    clientId: client.clientId,
    data: {
      campaigns: campaigns.map(c => ({
        id: c.id,
        name: c.name,
        status: c.status,
        effectiveStatus: c.effective_status,
        objective: c.objective,
        dailyBudget: c.daily_budget ? parseInt(c.daily_budget) / 100 : null
      })),
      summary: {
        totalSpend: spend,
        reportedLeads,
        trueLeads,
        blendedCpl: blendedCpl ? parseFloat(blendedCpl.toFixed(2)) : null,
        trueCpl: trueCpl ? parseFloat(trueCpl.toFixed(2)) : null,
        cpm: parseFloat(cpm.toFixed(2)),
        ctr: parseFloat(ctr.toFixed(2)),
        frequency: parseFloat(frequency.toFixed(2)),
        doubleCount,
        inflation: inflation + '%',
        alerts
      }
    }
  }
}];
